const src = $input.first().json;
const exec = src.execution || {};
const wf = src.workflow || {};
const err = exec.error || {};

const message = String(err.message || 'Unknown error');
const failedNode = (err.node && err.node.name) || exec.lastNodeExecuted || 'Unknown node';
const failedNodeType = (err.node && err.node.type) || '';

let errorType = 'Unclassified';
let severity = 'Critical';

if (/401|403|unauthor|forbidden|invalid api key|credential/i.test(message)) {
  errorType = 'Authentication';
  severity = 'Critical';
} else if (/429|rate.?limit|quota|too many requests/i.test(message)) {
  errorType = 'Rate limit';
  severity = 'Warning';
} else if (/ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|socket hang up|timeout|502|503|504/i.test(message)) {
  errorType = 'Transient network';
  severity = 'Warning';
} else if (/cannot read|is not a function|undefined|is not iterable/i.test(message)) {
  errorType = 'Unexpected data shape';
  severity = 'Critical';
} else if (/required|missing|not found|does not exist/i.test(message)) {
  errorType = 'Configuration';
  severity = 'Critical';
}

return [{
  json: {
    failed_at: new Date().toISOString(),
    workflow_name: wf.name || 'Unknown workflow',
    workflow_id: wf.id || '',
    execution_id: String(exec.id || ''),
    execution_url: exec.url || '',
    failed_node: failedNode,
    failed_node_type: failedNodeType,
    error_message: message.slice(0, 900),
    error_type: errorType,
    severity: severity,
    is_retry: Boolean(exec.retryOf)
  }
}];

